    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID) internal {
        vm.assume(true);
        bool reverted;
        try c.approveTransfer(address(this), loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 loanID) public {
        _run(loanID);
    }

    receive() external payable {}
}
